import requests, xml.etree.ElementTree as ET
queries=['("groove pancreatic carcinoma" OR "groove adenocarcinoma" OR "pancreaticoduodenal groove" adenocarcinoma)','("groove" AND pancreatic AND SMAD4) OR ("groove" AND pancreatic AND DPC4)']
for q in queries:
 p={'db':'pubmed','term':q+' AND 1900:2025[dp]','retmode':'json','retmax':40,'sort':'relevance'}
 ids=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params=p,timeout=30).json()['esearchresult']['idlist']
 print('\nQUERY',q,'N',len(ids),ids)
 if ids:
  xml=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'xml'},timeout=30).text
  root=ET.fromstring(xml)
  for a in root.findall('.//PubmedArticle'):
   pm=a.findtext('.//PMID'); title=''.join(a.find('.//ArticleTitle').itertext()) if a.find('.//ArticleTitle') is not None else ''
   abst=' '.join(''.join(x.itertext()) for x in a.findall('.//Abstract/AbstractText'))
   if any(w in (title+' '+abst).lower() for w in ['smad4','dpc4','well-different','differentiated','groove']): print(pm,title,'\n',abst[:1800])
